103: fn handle(mut stream: TcpStream, state: Arc<Mutex<Engine>>) {
104:     let mut buffer = vec![0u8; 8192];
105:     let n = match stream.read(&mut buffer) { Ok(n) if n > 0 => n, _ => return };
106:     let request = String::from_utf8_lossy(&buffer[..n]);
107:     let line = request.lines().next().unwrap_or("");
108:     if line.starts_with("OPTIONS ") { response(&mut stream, "204 No Content", "text/plain", b""); return; }
109:     if line.starts_with("GET / ") || line.starts_with("GET /index.html") {
110:         let page = include_str!("../../index.html"); response(&mut stream, "200 OK", "text/html; charset=utf-8", page.as_bytes()); return;
111:     }
112:     if line.starts_with("GET /api/state") {
113:         let json = state.lock().unwrap().json(); response(&mut stream, "200 OK", "application/json", json.as_bytes()); return;
114:     }
115:     if line.starts_with("POST /api/reset") {
116:         *state.lock().unwrap() = Engine::new(); let json = state.lock().unwrap().json(); response(&mut stream, "200 OK", "application/json", json.as_bytes()); return;
117:     }
118:     if line.starts_with("POST /api/tick") {
119:         let body = request.split("\r\n\r\n").nth(1).unwrap_or("");
120:         let mut engine = state.lock().unwrap(); engine.tick(body); let json = engine.json(); drop(engine);
121:         response(&mut stream, "200 OK", "application/json", json.as_bytes()); return;
122:     }
123:     response(&mut stream, "404 Not Found", "text/plain", b"not found");
124: }
